import{_ as t,o as r,c as a,a2 as s}from"./chunks/framework.DYAmjhAm.js";const p=JSON.parse('{"title":"Using a Breeze .NET server","description":"","frontmatter":{},"headers":[],"relativePath":"server/dotnet.md","filePath":"server/dotnet.md","lastUpdated":1790031546000}'),n={name:"server/dotnet.md"};function i(o,e,d,h,l,c){return r(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="using-a-breeze-net-server" tabindex="-1">Using a Breeze .NET server <a class="header-anchor" href="#using-a-breeze-net-server" aria-label="Permalink to &quot;Using a Breeze .NET server&quot;">​</a></h1><p>Breeze talks to any server that speaks HTTP and JSON, and the rest of this section is about making it fit one. This page is about the case where you control the server too, and it is .NET: then there is a matching server library, and most of the configuration on this page disappears.</p><p>The server packages live in <a href="https://github.com/Breeze/breeze-server-v3" target="_blank" rel="noreferrer">breeze-server-v3</a>, and have their own documentation — see <a href="#reading-the-server-docs">Reading the server docs</a>.</p><h2 id="what-you-get-for-free" tabindex="-1">What you get for free <a class="header-anchor" href="#what-you-get-for-free" aria-label="Permalink to &quot;What you get for free&quot;">​</a></h2><p>Against a Breeze .NET server the client needs <strong>no configuration at all</strong>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { EntityManager } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;breeze-client&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> em</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> EntityManager</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/breeze/Northwind&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Every default already matches what the server does.</p><table tabindex="0"><thead><tr><th>Piece</th><th>Default</th><th>Why it fits</th></tr></thead><tbody><tr><td>data service adapter</td><td><code>&#39;webApi&#39;</code></td><td>the request and response shapes the server produces</td></tr><tr><td>URI builder</td><td><code>&#39;json&#39;</code></td><td>the server reads Breeze JSON queries out of the URL</td></tr><tr><td><code>JsonResultsAdapter</code></td><td>supplied by the adapter</td><td>matches the <code>$type</code>/<code>$ref</code> JSON the server sends</td></tr><tr><td><code>NamingConvention</code></td><td><code>camelCase</code></td><td>the server sends .NET <code>PascalCase</code> names</td></tr><tr><td>metadata</td><td>fetched from the service</td><td>the server generates it from your EF or NHibernate mapping</td></tr></tbody></table><p>So the pages on <a href="/breeze-client-v3/server/transport">transport</a>, <a href="/breeze-client-v3/server/dataserviceadapter">DataServiceAdapter</a>, <a href="/breeze-client-v3/server/jsonresultsadapter">JSON results</a> and <a href="/breeze-client-v3/server/namingconvention">naming conventions</a> are about <em>other</em> servers. You need them here only to add something of your own — auth headers, say, which is <a href="/breeze-client-v3/server/transport">Supplying your own transport</a>.</p><h2 id="what-the-server-must-expose" tabindex="-1">What the server must expose <a class="header-anchor" href="#what-the-server-must-expose" aria-label="Permalink to &quot;What the server must expose&quot;">​</a></h2><p>Three things, at one service root:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><code>GET {root}/Metadata</code></td><td>the metadata document</td></tr><tr><td><code>GET {root}/{ResourceName}</code></td><td>one queryable endpoint per entity set</td></tr><tr><td><code>POST {root}/SaveChanges</code></td><td>every pending change, in one request</td></tr></tbody></table><p><code>new EntityManager(&#39;/breeze/Northwind&#39;)</code> sets the root; <code>EntityQuery.from(&#39;Customers&#39;)</code> picks the resource. On the server those are an action named <code>Customers</code> on a controller routed at <code>breeze/Northwind</code> — which is what the server&#39;s default routing produces.</p><h2 id="things-that-line-up-across-the-two-sides" tabindex="-1">Things that line up across the two sides <a class="header-anchor" href="#things-that-line-up-across-the-two-sides" aria-label="Permalink to &quot;Things that line up across the two sides&quot;">​</a></h2><p>A few decisions have to match, and they are the usual source of confusion:</p><ul><li><strong>Naming.</strong> The server sends <code>CompanyName</code>; the client&#39;s <code>camelCase</code> convention makes it <code>companyName</code>. If the server <em>also</em> camel-cases its JSON, the names get translated twice and stop matching the metadata. The server&#39;s JSON serializer setup takes a <code>camelCasing</code> flag that defaults to <code>false</code> — leave it there. See <a href="/breeze-client-v3/server/namingconvention">Naming conventions</a>.</li><li><strong>Enums.</strong> The server can send enum values as strings or as integers. The client reads what the metadata says the property is, so the two have to agree; strings are the default on both sides.</li><li><strong>Save errors.</strong> The server returns an RFC 9457 problem details document carrying per-entity errors, and the client turns those into <code>ValidationError</code>s on the entities that failed. See <a href="/breeze-client-v3/guide/error-handling">Error handling</a>.</li><li><strong>Temporary keys.</strong> The client invents a key for a new entity; the server sends back a mapping from that to the real one, and the client swaps it everywhere — including in the foreign keys of entities saved in the same batch. Nothing to configure, but it explains why a save response changes ids.</li></ul><h2 id="reading-the-server-docs" tabindex="-1">Reading the server docs <a class="header-anchor" href="#reading-the-server-docs" aria-label="Permalink to &quot;Reading the server docs&quot;">​</a></h2><p>The server documentation is its own site, at <strong><a href="https://breeze.github.io/breeze-server-v3/" target="_blank" rel="noreferrer">breeze.github.io/breeze-server-v3</a></strong> — hand-written guides plus the <a href="https://breeze.github.io/breeze-server-v3/api/" target="_blank" rel="noreferrer">.NET API reference</a>, generated from the XML doc comments. What is there:</p><table tabindex="0"><thead><tr><th>Page</th><th>About</th></tr></thead><tbody><tr><td><a href="https://breeze.github.io/breeze-server-v3/guide/getting-started.html" target="_blank" rel="noreferrer">Getting started</a></td><td>from an empty ASP.NET Core project to a working Breeze endpoint</td></tr><tr><td><a href="https://breeze.github.io/breeze-server-v3/guide/persistence-manager.html" target="_blank" rel="noreferrer">The PersistenceManager</a></td><td>the server-side counterpart of <code>EntityManager</code></td></tr><tr><td><a href="https://breeze.github.io/breeze-server-v3/guide/querying.html" target="_blank" rel="noreferrer">Querying</a></td><td>how a client&#39;s query becomes SQL, and how to bound what clients may ask for</td></tr><tr><td><a href="https://breeze.github.io/breeze-server-v3/guide/saving.html" target="_blank" rel="noreferrer">Saving</a></td><td>save interceptors, transactions and key mappings</td></tr><tr><td><a href="https://breeze.github.io/breeze-server-v3/guide/metadata.html" target="_blank" rel="noreferrer">Metadata</a></td><td>what the client is told about the model, and how to change it</td></tr><tr><td><a href="https://breeze.github.io/breeze-server-v3/guide/error-handling.html" target="_blank" rel="noreferrer">Error handling</a></td><td>returning validation and concurrency errors this client understands</td></tr><tr><td><a href="https://breeze.github.io/breeze-server-v3/api/" target="_blank" rel="noreferrer">API reference</a></td><td>every public type in the five server packages</td></tr></tbody></table><p>To build it yourself — to preview a change, or to read it offline — clone <a href="https://github.com/Breeze/breeze-server-v3" target="_blank" rel="noreferrer">breeze-server-v3</a> and follow its <a href="https://github.com/Breeze/breeze-server-v3/blob/master/DOCS.md" target="_blank" rel="noreferrer">DOCS.md</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/breeze-client-v3/server/">Overview</a> — the pieces the client uses to talk to any server</li><li><a href="/breeze-client-v3/guide/getting-started">Getting started</a> — the client side</li><li><a href="/breeze-client-v3/guide/saving-changes">Saving changes</a></li></ul>`,22)])])}const v=t(n,[["render",i]]);export{p as __pageData,v as default};
